# NAME<TAB>TYPE rows; TYPE is 'bool' for options that only take true/false.
_helper_mitmweb_option_types() {
    _argc_util_cache 3600 _helper_mitmweb_option_types_uncached mitmweb_option_types
}

_helper_mitmweb_option_types_uncached() {
    mitmweb --options 2>/dev/null | gawk '
        /^#/ { comment = comment " " $0; next }
        /^[a-z_][a-z0-9_]*:/ {
            name = $0
            sub(/:.*/, "", name)
            print name "\t" (comment ~ /Type bool/ ? "bool" : "")
            comment = ""
        }
    '
}
